  "Tap the ground to place a cracker, then Fire. Drag to look around.": "ಪಟಾಕಿ ಇಡಲು ನೆಲವನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ ಸಿಡಿಸು. ಸುತ್ತಲೂ ನೋಡಲು ಎಳೆಯಿರಿ.",
