  "Thank You": "ಧನ್ಯವಾದಗಳು",
  "Thank you for the lovely wishes! Sending a sky full of light right back to you.": "ಸುಂದರ ಶುಭಾಶಯಗಳಿಗೆ ಧನ್ಯವಾದಗಳು! ನಿಮಗೆ ಮರಳಿ ಬೆಳಕು ತುಂಬಿದ ಆಕಾಶ ಕಳುಹಿಸುತ್ತಿದ್ದೇನೆ.",
  "Thank you,": "ಧನ್ಯವಾದಗಳು,",
  "That code isn’t valid": "ಆ ಕೋಡ್ ಮಾನ್ಯವಲ್ಲ",
  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "ನಿಮಗೆ ನೆನಪಿಸಲು, ಹುಟ್ಟುಹಬ್ಬ ಇರುವ ಕಾಂಟ್ಯಾಕ್ಟ್‌ಗಳ ಹೆಸರು, ಹುಟ್ಟುಹಬ್ಬ ಮತ್ತು ಫೋಟೋಗಳನ್ನು ಆ್ಯಪ್ ಓದುತ್ತದೆ. ಅವು ಈ ಫೋನ್‌ನಲ್ಲೇ ಇರುತ್ತವೆ, ಎಂದಿಗೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "ದೊಡ್ಡ ಪಟಾಕಿಗಳಿಗೆ ಜೆಮ್ಸ್ ಬೇಕು. ದಿನನಿತ್ಯದ ಪಟಾಕಿಗಳು ಮತ್ತು ಸುರುಸುರು ಬತ್ತಿ ಬರಹ ಯಾವಾಗಲೂ ಉಚಿತ.",
  "The camera is busy. Using the camera view instead.": "ಕ್ಯಾಮೆರಾ ಬ್ಯುಸಿ ಇದೆ. ಬದಲಿಗೆ ಕ್ಯಾಮೆರಾ ವ್ಯೂ ಬಳಸಲಾಗುತ್ತಿದೆ.",
  "The headline flies across the sky; the message appears on the card.": "ಶೀರ್ಷಿಕೆ ಆಕಾಶದಲ್ಲಿ ಹಾರುತ್ತದೆ; ಸಂದೇಶ ಕಾರ್ಡ್‌ನಲ್ಲಿ ಕಾಣುತ್ತದೆ.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "ಲಿಂಕ್‌ನಲ್ಲೇ ಇಡೀ ಕಾರ್ಡ್ ಇದೆ, ಹಾಗಾಗಿ ಏನೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ. ಅದನ್ನು ತೆರೆಯುವ ಯಾರಾದರೂ ಶೋ ನೋಡಬಹುದು.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "ಲಿಂಕ್‌ನಲ್ಲೇ ಇಡೀ ಕಾರ್ಡ್ ಇದೆ, ಹಾಗಾಗಿ ಏನೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ. ಸ್ನೇಹಿತರು ಲಿಂಕ್ ತೆರೆಯಲು ಸಾಧ್ಯವಾಗುವಂತೆ ಗೇಮ್ ಅನ್ನು ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಹೋಸ್ಟ್ ಮಾಡಿ (ಉದಾಹರಣೆಗೆ GitHub Pages ಅಥವಾ Netlify).",
