  "Who is it for? Their name is written in fireworks.": "ಇದು ಯಾರಿಗಾಗಿ? ಅವರ ಹೆಸರನ್ನು ಪಟಾಕಿಗಳಲ್ಲಿ ಬರೆಯಲಾಗುತ್ತದೆ.",
