  "Why are you lighting them up?": "ನೀವು ಅವರನ್ನು ಏಕೆ ಬೆಳಗಿಸುತ್ತಿದ್ದೀರಿ?",
  "Willow": "ವಿಲ್ಲೋ",
  "Wish": "ಶುಭಾಶಯ",
  "Wishing you a year full of light, laughter and wonderful surprises.": "ಬೆಳಕು, ನಗು ಮತ್ತು ಅದ್ಭುತ ಅಚ್ಚರಿಗಳಿಂದ ತುಂಬಿದ ವರ್ಷ ನಿಮ್ಮದಾಗಲಿ.",
  "Wishing you sweets, sparkle and the warmth of family this Diwali.": "ಈ ದೀಪಾವಳಿಗೆ ನಿಮಗೆ ಸಿಹಿ, ಹೊಳಪು ಮತ್ತು ಕುಟುಂಬದ ಆತ್ಮೀಯತೆ ಸಿಗಲಿ.",
  "With you, every ordinary day feels like a celebration.": "ನಿನ್ನೊಂದಿಗೆ, ಪ್ರತಿ ಸಾಮಾನ್ಯ ದಿನವೂ ಹಬ್ಬದಂತೆ ಅನಿಸುತ್ತದೆ.",
  "Worlds of India": "ಭಾರತದ ಲೋಕಗಳು",
  "Write a name, it goes up in the sky": "ಒಂದು ಹೆಸರು ಬರೆಯಿರಿ, ಅದು ಆಕಾಶಕ್ಕೆ ಹಾರುತ್ತದೆ",
  "Write a review": "ರಿವ್ಯೂ ಬರೆಯಿರಿ",
