  "Work is better with you around. Here are a few reasons why": "ನೀವಿದ್ದರೆ ಕೆಲಸ ಇನ್ನಷ್ಟು ಚೆನ್ನಾಗಿರುತ್ತದೆ. ಏಕೆಂದರೆ",
