  "I admire how calm you stay under pressure": "ಒತ್ತಡದಲ್ಲೂ ನೀವು ಶಾಂತವಾಗಿರುವುದು ನನಗೆ ಮೆಚ್ಚುಗೆ",
  "I love our tea breaks and quick laughs between meetings": "ಮೀಟಿಂಗ್‌ಗಳ ನಡುವಿನ ನಮ್ಮ ಟೀ ಬ್ರೇಕ್ ಮತ್ತು ನಗು ನನಗಿಷ್ಟ",
  "Every project with you feels like a team win": "ನಿಮ್ಮ ಜೊತೆಗಿನ ಪ್ರತಿ ಪ್ರಾಜೆಕ್ಟ್ ತಂಡದ ಗೆಲುವಿನಂತೆ",
  "I still remember how you helped me on my first day": "ನನ್ನ ಮೊದಲ ದಿನ ನೀವು ಸಹಾಯ ಮಾಡಿದ್ದು ಈಗಲೂ ನೆನಪಿದೆ",
  "When deadlines piled up, you always had my back": "ಡೆಡ್‌ಲೈನ್‌ಗಳು ರಾಶಿಯಾದಾಗ, ನೀವು ಯಾವಾಗಲೂ ನನ್ನ ಬೆನ್ನಿಗೆ ನಿಂತಿರಿ",
  "Thanks for always sharing what you know": "ನಿಮಗೆ ಗೊತ್ತಿರುವುದನ್ನು ಯಾವಾಗಲೂ ಹಂಚಿಕೊಂಡಿದ್ದಕ್ಕೆ ಧನ್ಯವಾದ",
  "Thank you for your patience and good humour": "ನಿಮ್ಮ ತಾಳ್ಮೆ ಮತ್ತು ಹಾಸ್ಯಪ್ರಜ್ಞೆಗೆ ಧನ್ಯವಾದ",
  "Your hard work inspires the whole team": "ನಿಮ್ಮ ಶ್ರಮ ಇಡೀ ತಂಡಕ್ಕೆ ಸ್ಫೂರ್ತಿ",
  "Lucky to work with someone like you": "ನಿಮ್ಮಂಥವರ ಜೊತೆ ಕೆಲಸ ಮಾಡುವುದು ನನ್ನ ಭಾಗ್ಯ",
  "Another year of you is the best gift for all of us": "ನಿನ್ನ ಇನ್ನೊಂದು ವರ್ಷವೇ ನಮ್ಮೆಲ್ಲರಿಗೂ ದೊಡ್ಡ ಉಡುಗೊರೆ",
  "Every birthday, you shine a little brighter": "ಪ್ರತಿ ಹುಟ್ಟುಹಬ್ಬಕ್ಕೂ ನೀನು ಇನ್ನಷ್ಟು ಹೊಳೆಯುತ್ತೀಯ",
  "You bring more light than every diya this Diwali": "ಈ ದೀಪಾವಳಿಯ ಎಲ್ಲಾ ಹಣತೆಗಳಿಗಿಂತ ನೀನೇ ಹೆಚ್ಚು ಬೆಳಕು ತರುತ್ತೀಯ",
  "Celebrating Diwali with you feels like home": "ನಿನ್ನ ಜೊತೆ ದೀಪಾವಳಿ ಆಚರಿಸುವುದು ಮನೆಯಂತೆ ಅನಿಸುತ್ತದೆ",
  "You add colour to my life every single day": "ಪ್ರತಿದಿನ ನೀನು ನನ್ನ ಜೀವನಕ್ಕೆ ಬಣ್ಣ ತುಂಬುತ್ತೀಯ",
  "You make every season feel merry and bright": "ನೀನು ಪ್ರತಿ ಹಬ್ಬವನ್ನೂ ಸಂತಸ ಮತ್ತು ಬೆಳಕಿನಿಂದ ತುಂಬುತ್ತೀಯ",
  "I can’t wait to share another year with you": "ನಿನ್ನ ಜೊತೆ ಇನ್ನೊಂದು ವರ್ಷ ಹಂಚಿಕೊಳ್ಳಲು ಕಾಯುತ್ತಿದ್ದೇನೆ",
  "Every year together is better than the one before": "ಜೊತೆಯಾಗಿರುವ ಪ್ರತಿ ವರ್ಷವೂ ಹಿಂದಿನದಕ್ಕಿಂತ ಚೆಂದ",
  "Here’s to all the years still to come": "ಇನ್ನೂ ಬರಲಿರುವ ಎಲ್ಲಾ ವರ್ಷಗಳಿಗಾಗಿ!",
  "Today begins your happily ever after": "ಇಂದಿನಿಂದ ನಿಮ್ಮ ಸುಖದ ಕಥೆ ಶುರು",
  "You two make love look easy": "ನೀವಿಬ್ಬರು ಪ್ರೀತಿಯನ್ನು ಸುಲಭವೆನಿಸುವಂತೆ ಮಾಡುತ್ತೀರಿ",
  "You worked so hard for this, and it shows": "ಇದಕ್ಕಾಗಿ ನೀನು ತುಂಬಾ ಶ್ರಮಪಟ್ಟೆ, ಅದು ಕಾಣುತ್ತಿದೆ",
  "All those late nights of study were worth it": "ಓದಿನ ಆ ಎಲ್ಲಾ ತಡರಾತ್ರಿಗಳು ಸಾರ್ಥಕವಾದವು",
  "They are so lucky to have you": "ನೀನು ಸಿಕ್ಕಿರುವುದು ಅವರ ಭಾಗ್ಯ",
  "You earned every bit of the rest ahead": "ಮುಂದಿರುವ ವಿಶ್ರಾಂತಿಯ ಪ್ರತಿ ಕ್ಷಣವನ್ನೂ ನೀವು ಗಳಿಸಿದ್ದೀರಿ",
  "You are stronger than anything you’re facing": "ನೀನು ಎದುರಿಸುತ್ತಿರುವ ಎಲ್ಲದಕ್ಕಿಂತ ನೀನು ಬಲಶಾಲಿ",
  "You matter more to me than being right": "ನಾನೇ ಸರಿ ಎನ್ನುವುದಕ್ಕಿಂತ ನೀನು ನನಗೆ ಮುಖ್ಯ",
  "Every day feels a little dimmer without you": "ನೀನಿಲ್ಲದೆ ಪ್ರತಿದಿನವೂ ಸ್ವಲ್ಪ ಮಸುಕು",
  "You make every day feel full of love": "ನೀನು ಪ್ರತಿದಿನವನ್ನೂ ಪ್ರೀತಿಯಿಂದ ತುಂಬುತ್ತೀಯ",
  "You show what a wonderful mom looks like": "ಅದ್ಭುತ ಅಮ್ಮ ಹೇಗಿರುತ್ತಾಳೆ ಎಂದು ನೀನು ತೋರಿಸುತ್ತೀಯ",
  "You show what a great dad looks like": "ಅದ್ಭುತ ಅಪ್ಪ ಹೇಗಿರುತ್ತಾನೆ ಎಂದು ನೀನು ತೋರಿಸುತ್ತೀಯ",
  "Every day is Friendship Day with you": "ನಿನ್ನ ಜೊತೆ ಪ್ರತಿದಿನವೂ ಸ್ನೇಹ ದಿನ",
  "Today the whole class says thank you": "ಇಂದು ಇಡೀ ತರಗತಿ ಧನ್ಯವಾದ ಹೇಳುತ್ತಿದೆ",
  "This bond grows stronger with every Rakhi": "ಪ್ರತಿ ರಾಖಿಯೊಂದಿಗೆ ಈ ಬಂಧ ಇನ್ನಷ್ಟು ಗಟ್ಟಿಯಾಗುತ್ತದೆ",
  "Bonds like yours make every festival brighter": "ನಿಮ್ಮಂಥ ಬಂಧಗಳು ಪ್ರತಿ ಹಬ್ಬವನ್ನೂ ಬೆಳಗಿಸುತ್ತವೆ",
  "Your love and faith inspire everyone around you": "ನಿಮ್ಮ ಪ್ರೀತಿ ಮತ್ತು ಶ್ರದ್ಧೆ ಸುತ್ತಲಿನ ಎಲ್ಲರಿಗೂ ಸ್ಫೂರ್ತಿ",
