  "No ads, every cracker free and 1,000 levels each in Diya Path and Rocket Rush, all through the festival.": "ಜಾಹೀರಾತುಗಳಿಲ್ಲ, ಎಲ್ಲ ಪಟಾಕಿ ಉಚಿತ, ಹಣತೆ ಹಾದಿ ಮತ್ತು ರಾಕೆಟ್ ರಶ್ ಪ್ರತಿಯೊಂದರಲ್ಲಿ 1,000 ಲೆವೆಲ್‌ಗಳು, ಹಬ್ಬದುದ್ದಕ್ಕೂ.",
  "Unlock 1,000 levels each in Diya Path and Rocket Rush": "ಹಣತೆ ಹಾದಿ ಮತ್ತು ರಾಕೆಟ್ ರಶ್ ಪ್ರತಿಯೊಂದರಲ್ಲಿ 1,000 ಲೆವೆಲ್‌ಗಳನ್ನು ತೆರೆಯಿರಿ",
  "No ads · every cracker free with Premium": "ಜಾಹೀರಾತುಗಳಿಲ್ಲ · Premium ಜೊತೆ ಎಲ್ಲ ಪಟಾಕಿ ಉಚಿತ",
  "Grand finales, 3D skylines, AR, and 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "ಗ್ರ್ಯಾಂಡ್ ಫಿನಾಲೆ, 3D ಸ್ಕೈಲೈನ್‌ಗಳು, AR, ಮತ್ತು ಹಣತೆ ಹಾದಿ, ರಾಕೆಟ್ ರಶ್ ಪ್ರತಿಯೊಂದರಲ್ಲಿ 1,000 ಲೆವೆಲ್‌ಗಳು, ಅನಿಯಮಿತ ಸುಳಿವುಗಳೊಂದಿಗೆ.",
  "Premium makes every cracker free and opens 1,000 levels each in Diya Path and Rocket Rush with unlimited hints.": "Premium ಎಲ್ಲ ಪಟಾಕಿಗಳನ್ನು ಉಚಿತಗೊಳಿಸಿ, ಹಣತೆ ಹಾದಿ, ರಾಕೆಟ್ ರಶ್ ಪ್ರತಿಯೊಂದರಲ್ಲಿ 1,000 ಲೆವೆಲ್‌ಗಳನ್ನು ತೆರೆಯುತ್ತದೆ, ಅನಿಯಮಿತ ಸುಳಿವುಗಳೊಂದಿಗೆ.",
