  "All 15 landmarks in 3D, and the sacred Diya Path backgrounds.": "ಎಲ್ಲಾ 15 ಸ್ಮಾರಕಗಳು 3D ಯಲ್ಲಿ, ಮತ್ತು ದೀಯಾ ಪಾತ್‌ನ ಪವಿತ್ರ ಹಿನ್ನೆಲೆಗಳು.",
  "A safer streak": "ಹೆಚ್ಚು ಸುರಕ್ಷಿತ ಸ್ಟ್ರೀಕ್",
  "Miss a day twice a week and keep your streak and its bigger gifts.": "ವಾರಕ್ಕೆ ಎರಡು ಬಾರಿ ಒಂದು ದಿನ ತಪ್ಪಿಸಿದರೂ ಸ್ಟ್ರೀಕ್ ಮತ್ತು ಅದರ ದೊಡ್ಡ ಉಡುಗೊರೆಗಳು ಉಳಿಯುತ್ತವೆ.",
  "You’ve lit {0} kinds of crackers so far. With Premium, all {1} are free.": "ನೀವು ಇದುವರೆಗೆ {0} ಬಗೆಯ ಪಟಾಕಿಗಳನ್ನು ಹಚ್ಚಿದ್ದೀರಿ. Premium ನಲ್ಲಿ ಎಲ್ಲಾ {1} ಉಚಿತ.",
  "It’s Diwali week. Light the whole street.": "ಇದು ದೀಪಾವಳಿ ವಾರ. ಇಡೀ ಬೀದಿಯನ್ನು ಬೆಳಗಿಸಿ.",
  "Diwali is tomorrow. Light the whole street.": "ನಾಳೆ ದೀಪಾವಳಿ. ಇಡೀ ಬೀದಿಯನ್ನು ಬೆಳಗಿಸಿ.",
  "Diwali is in {0} days. Light the whole street.": "ದೀಪಾವಳಿಗೆ ಇನ್ನು {0} ದಿನಗಳು. ಇಡೀ ಬೀದಿಯನ್ನು ಬೆಳಗಿಸಿ.",
  "Changed your mind? You can ask Google Play for a refund within 48 hours of buying.": "ಮನಸ್ಸು ಬದಲಾಯಿತೇ? ಖರೀದಿಸಿದ 48 ಗಂಟೆಗಳೊಳಗೆ Google Play ನಲ್ಲಿ ಮರುಪಾವತಿ ಕೇಳಬಹುದು.",
  "Any time": "ಯಾವಾಗ ಬೇಕಾದರೂ",
  "A thousand crackers on a bamboo pole": "ಬಿದಿರಿನ ಕಂಬದ ಮೇಲೆ ಸಾವಿರ ಪಟಾಕಿಗಳು",
  "Every cracker free": "ಪ್ರತಿ ಪಟಾಕಿ ಉಚಿತ",
  "Finales, saravedi and seven shots, every night": "ಫಿನಾಲೆ, ಸರವೇಡಿ ಮತ್ತು ಸೆವೆನ್ ಶಾಟ್, ಪ್ರತಿ ರಾತ್ರಿ",
  "Five Premium crackers": "ಐದು Premium ಪಟಾಕಿಗಳು",
  "The thousand-cracker Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi. One free try each.": "ಸಾವಿರ ಪಟಾಕಿಗಳ ಸಾವಿರ ಲಡಿ, ಸರವೇಡಿ, ಸೆವೆನ್ ಶಾಟ್, ಡಬಲ್ ಶಾಟ್ ಮತ್ತು ಲಕ್ಷ್ಮಿ ಪಟಾಕಿ. ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು ಉಚಿತ ಪ್ರಯತ್ನ.",
  "Grand finales, wedding cakes, sutli bombs and more. One of each costs {0} without Premium.": "ಗ್ರ್ಯಾಂಡ್ ಫಿನಾಲೆ, ವೆಡ್ಡಿಂಗ್ ಕೇಕ್, ಸುತ್ಲಿ ಬಾಂಬ್ ಮತ್ತು ಇನ್ನೂ ಹಲವು. Premium ಇಲ್ಲದೆ ಪ್ರತಿಯೊಂದನ್ನೂ ಒಮ್ಮೆ ಹಚ್ಚಲು {0} ಬೇಕು.",
  "A grand finale and a wedding cake every evening for a month: {0} (about {1} at gem-pack prices). With Premium they’re free, with everything above.": "ಒಂದು ತಿಂಗಳು ಪ್ರತಿ ಸಂಜೆ ಒಂದು ಗ್ರ್ಯಾಂಡ್ ಫಿನಾಲೆ ಮತ್ತು ಒಂದು ವೆಡ್ಡಿಂಗ್ ಕೇಕ್: {0} (ಜೆಮ್ ಪ್ಯಾಕ್ ಬೆಲೆಯಲ್ಲಿ ಸುಮಾರು {1}). Premium ನಲ್ಲಿ ಇವು ಉಚಿತ, ಮೇಲಿನ ಎಲ್ಲದರ ಜೊತೆಗೆ.",
  "A grand finale and a wedding cake every evening for a month: {0}. With Premium they’re free, with everything above.": "ಒಂದು ತಿಂಗಳು ಪ್ರತಿ ಸಂಜೆ ಒಂದು ಗ್ರ್ಯಾಂಡ್ ಫಿನಾಲೆ ಮತ್ತು ಒಂದು ವೆಡ್ಡಿಂಗ್ ಕೇಕ್: {0}. Premium ನಲ್ಲಿ ಇವು ಉಚಿತ, ಮೇಲಿನ ಎಲ್ಲದರ ಜೊತೆಗೆ.",
  "Light the {0} with Premium": "Premium ನೊಂದಿಗೆ {0} ಹಚ್ಚಿ",
  "Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi, lit with your sparkler. Plus no ads and every cracker free.": "ಸಾವಿರ ಲಡಿ, ಸರವೇಡಿ, ಸೆವೆನ್ ಶಾಟ್, ಡಬಲ್ ಶಾಟ್ ಮತ್ತು ಲಕ್ಷ್ಮಿ ಪಟಾಕಿ, ನಿಮ್ಮ ಸುರುಸುರು ಬತ್ತಿಯಿಂದ ಹಚ್ಚಿ. ಜೊತೆಗೆ ಜಾಹೀರಾತುಗಳಿಲ್ಲ, ಪ್ರತಿ ಪಟಾಕಿಯೂ ಉಚಿತ.",
